from itertools import zip_longest

from scipy.spatial import distance


def _normalize_point(point):
    """Return a 2D coordinate for a point-like input.

    A bare number (such as ``4``) and a single-element tuple (such as
    ``(4,)``) both mean that the x and y coordinates are equal to that
    number.
    """
    if isinstance(point, tuple):
        if len(point) == 1:
            return (point[0], point[0])
        return point
    return (point, point)


def task_func(points):
    """Calculate Euclidean distances between consecutive 2D points."""
    if len(points) < 2:
        return []

    normalized = [_normalize_point(point) for point in points]
    return [
        float(distance.euclidean(first, second))
        for first, second in zip_longest(normalized, normalized[1:])
        if second is not None
    ]
